SELECT 
  FROM PST P
 WHERE P.PST_SN = #{pstSn}
   AND P.PST_STTS_CD = #{pstSttsCd}

SELECT MBR_NCNM
  FROM MBR
 WHERE MBR_SN = #{mbrSn}

SELECT EXISTS (SELECT 1
                 FROM PST_RCMDTN
                WHERE PST_SN = #{pstSn}
                  AND MBR_SN = #{mbrSn}
                  AND USE_YN = 'Y')

SELECT RCMDTN_CNT
  FROM PST
 WHERE PST_SN = #{pstSn}

mapper.insert:
INSERT INTO PST_STTS_HSTRY
     ( PST_SN
     , MBR_SN
     , BFR_STTS_CD
     , AFTR_STTS_CD
     , CHG_RSN
     , REG_DT )
VALUES
     ( #{pstSn}
     , #{mbrSn}
     , #{bfrSttsCd}
     , #{aftrSttsCd}
     , #{chgRsn}
     , NOW() )

mapper.update:
UPDATE PST
BBS_CD = #{bbsCd}, PST_TTL = #{pstTtl}, PST_CN = #{pstCn}, MDFR_ID = #{actorId}, MDFCN_DT = NOW()
WHERE PST_SN = #{pstSn} AND PST_STTS_CD = #{pstSttsCd}

UPDATE PST
   SET PST_STTS_CD = #{afterCd}
     , MDFR_ID = #{actorId}
     , MDFCN_DT = NOW()
 WHERE PST_SN = #{pstSn}
   AND PST_STTS_CD = #{beforeCd}

UPDATE PST_IMG
   SET DEL_YN = 'Y'
     , MDFR_ID = #{actorId}
     , MDFCN_DT = NOW()
 WHERE PST_SN = #{pstSn}
   AND DEL_YN = 'N'
   AND ATCH_FILE_SN IN

       #{atchFileSn}

UPDATE PST_RCMDTN
   SET USE_YN = 'Y'
     , MDFCN_DT = NOW()
 WHERE PST_SN = #{pstSn}
   AND MBR_SN = #{mbrSn}
   AND USE_YN = 'N'

UPDATE PST_RCMDTN
   SET USE_YN = 'N'
     , MDFCN_DT = NOW()
 WHERE PST_SN = #{pstSn}
   AND MBR_SN = #{mbrSn}
   AND USE_YN = 'Y'
